Hi everyone,

I realise I've posted a few threads on this forum already but I keep running into fresh issues. I'm running a multisite multistate CJS model which seems to be going well but some of my capture probabilities are showing strange traceplots, see attached. I can provide full code, but I'll just provide code for capture probabilities first to see if the problem can already be diagnosed. Surveys were conducted in the robust design so there's an extra j loop for secondary surveys:

for(m in 1:n.site){
    for(i in 1:n.ind[m]){
      for(t in 1:(n.primary-1)){
        for(j in 1:n.secondary){
          logit(pU[i,t,j,m]) <- p.x[1,m] + p.x[2,m]*sex[i,m] + p.t[t,m]
          logit(pI[i,t,j,m]) <- p.x[1,m] + p.x[2,m]*sex[i,m] + p.x[3,m] + p.t[t,m]
}
}
}
}

Capture probabilities are of uninfected (pU) and infected (pI) individuals. p.x[1:2,m] are site-specific intercepts and effects of sex, p.x[3,m] is the effect on capture probability of being infected, and p.t[t,m] is a random temporal effect. The priors for p.x are this:

for(m in 1:n.site){
    pU.0[m] <- ilogit(p.x[1,m]) # Intercept on the probability scale
    p.x[1,m] ~ dnorm(0, sd = 1.5)
    p.x[2,m] ~ dnorm(0, sd = 1.5)
    p.x[3,m] ~ dnorm(0, sd = 1.5)
}

Initial values for this parameter (the rest is omitted):
function() list(p.x = array(runif(3*n.site,-1,1), c(3,n.site)))

The model runs fine and I don't get any error messages, but the traceplots look off. For some reason, p.x[1:3,3] are estimated just fine, but p.x[1:3,1:2] don't seem to sample (the screenshot only shows p.x[1:3,2], but p.x[1:3,1] is the same). I am also deriving the site-specific mean capture probability per primary occasion, and those estimates also look reasonable....

Any ideas?

Kind regards,
Matt

Good afternoon,

I am trying to run a "simple" CJS model with individual heterogeneity with NIMBLE. The code works fine with one sample, however, when I include a loop at the beginning of the code to run it for several different samples a get different errors or even R crashes.
I am new on NIMBLE so I am not sure what is happening or whereas I have to indicate that loop differently. Any help would be appreciated. Thanks.
Below is the code:

code1 <- nimbleCode( {

  for (i in 1:nind){
    for (t in f[i]:(n.occasions-1)){
      logit(phi[i,t]) <- alpha[x[i,t]] + beta[t] + epsilon[i]
      p[i,t] <- alpha.p[x[i,t]]
    }
  }

  # Priors
  for (i in 1:nind){
    epsilon[i] ~ dnorm(0,tau)
  }

  ## To avoid the lack of identifiability
  ## we set alpha[1]=0

  for (t in 1:(n.occasions-1)){
    beta[t] ~ dnorm(mu, tau.beta)
  }
  tau.beta <- 1/(sigma.s*sigma.s)
  sigma.s ~ dunif(0,10)
  mu ~ dnorm(0,0.1)

  alpha[1] <- 0

  for (u in 2:4){
    alpha[u] ~ dnorm(0,0.25)
  }

  for (u in 1:4){
    alpha.p[u] ~ dbeta(1,1)
  }

  sigma ~ dunif(0, 2)
  tau <- 1/(sigma*sigma)

  # Likelihood
  for (i in 1:nind){

    # Define latent state at first capture
    z[i,f[i]] ~ dbern(1)

    for (t in (f[i]+1):n.occasions){
      z[i,t] ~ dbern(mu1[i,t])
      mu1[i,t] <- phi[i,t-1]*z[i,t-1]

      # Observation process
      y[i,t] ~ dbern(mu2[i,t])
      mu2[i,t] <- p[i,t-1]*z[i,t]
    }
  }
}
)

################################################################
## Data, constants, initials
################################################################

set.seed(1)

## Functions
last.seen <- function(x) max(which(x!=0))
get.first <- function(x) min(which(x!=0))

for (s in 1:3){ ## Here is the problem!!!!

sub1 <- readRDS(paste0("subsample.real_", s, ".RDS"))

CH <- as.matrix(sub1[,-c(1,13:14)])

## Ringing vector
f <- apply(CH, 1, get.first)
l <- apply(CH, 1, last.seen)

## Create matrices X indicating age classes

x <- matrix(NA, ncol=dim(CH)[2]-1, nrow=dim(CH)[1])
vec.age <- c(1,2, 3, rep(4,7))
f.inverse <- dim(CH)[2]- f
for(i in 1:dim(CH)[1]){
  x[i,f[i]:dim(x)[2]] <- vec.age[1:f.inverse[i]]
}

## Known values of the latent variable Z (1's, 0's, NAs)
known.state.cjs <- function(ch){
  state <- ch
  for (i in 1:dim(ch)[1]){
    n1 <- min(which(ch[i,]==1))
    n2 <- max(which(ch[i,]==1))
    state[i, n1:n2] <- 1
  }
  state[state==0] <- NA
  return(state)
}

## Function  to create initial values of Z

cjs.init.z <- function(ch,f,l){
  inz <- ch
  for(i in 1:dim(ch)[1]){
    if(sum(ch[i,])==1) next
    n2 <- max(which(ch[i,]==1))
    inz[i, f[i]:n2] <- 1
  }
  for(i in 1: dim(ch)[1]){
    inz[i, 1:f[i]] <- NA
  }

  # To randomly add in time of death

  for(i in 1: dim(ch)[1]){
    if (l[i] != dim(ch)[2]) {
      death <- sample(c(l[i]:dim(ch)[2]),1)
      if (death != l[i]){
        for (j in (l[i]+1):death){
          inz[i,j] <- 1
        }
      }
    }
  }

  return(inz)
}

z <- known.state.cjs(CH)
z2 <- cjs.init.z(CH, f, l)
nind <- dim(CH)[1]
n.occasions <- dim(CH)[2]
y <- CH

inepsilon1 <- rnorm(nind,0,1)
inbeta <- rep(0,(n.occasions-1))

jags.data <- list(y=y,z=z)

constants <- list(nind=nind,n.occasions=n.occasions,x=x,f=f)

### Initial values
inits <- list(sigma=1, alpha=c(NA,2,1,1),alpha.p=c(0.02,0.2,0.4,0.4),z=z2,epsilon=inepsilon1,beta=inbeta)

### Parameters
parameters <- c("sigma", "alpha", "alpha.p","beta","sigma.s","mu")

NIMBLE_mod <- nimbleModel(code1, data=jags.data,
                          constants = constants,
                          inits = inits)

NIMBLE_real <- nimbleMCMC(code1, data=jags.data,constants = constants,
                          inits = inits, niter = 35000, nburnin = 1500,
                          thin = 1, nchains=1, monitors=parameters)

saveRDS(NIMBLE_real, paste0("NIMBLE_real", s, ".RDS"))

}
